/**
 * Attendance.js
 * -----------------------------------------------------------------------
 * Stores attendance generated by the Python face-recognition engine.
 * -----------------------------------------------------------------------
 */

const mongoose = require("mongoose");

const attendanceSchema = new mongoose.Schema(
  {
    // ---------------------------------------------------------
    // Student information
    // ---------------------------------------------------------

    studentId: {
      type: String,
      required: true,
      trim: true,
    },

    name: {
      type: String,
      required: true,
      trim: true,
    },

    // ---------------------------------------------------------
    // Teacher / class / session information
    // ---------------------------------------------------------

    teacherId: {
      type: String,
      required: true,
      trim: true,
    },

    sessionId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "AttendanceSession",
      required: true,
    },

    scheduleId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Schedule",
      required: true,
    },

    subject: {
      type: String,
      required: true,
      trim: true,
    },

    classDivision: {
      type: String,
      required: true,
      trim: true,
    },

    department: {
      type: String,
      trim: true,
    },

    academicYear: {
      type: String,
      trim: true,
    },

    division: {
      type: String,
      trim: true,
    },

    // ---------------------------------------------------------
    // Attendance information
    // ---------------------------------------------------------

    date: {
      type: String,
      required: true,
      trim: true,
    },

    time: {
      type: String,
      required: true,
      trim: true,
    },

    status: {
      type: String,
      required: true,
      enum: ["Present", "Absent"],
      default: "Present",
    },

    trackId: {
      type: Number,
      required: true,
    },

    similarity: {
      type: Number,
      required: true,
      min: 0,
      max: 1,
    },
  },
  {
    timestamps: true,
  }
);

// ---------------------------------------------------------
// Prevent duplicate attendance for same student/session
// ---------------------------------------------------------

attendanceSchema.index(
  {
    studentId: 1,
    sessionId: 1,
  },
  {
    unique: true,
  }
);

module.exports = mongoose.model(
  "Attendance",
  attendanceSchema
);